1	package pricing
2	
3	import (
4		"strings"
5		"testing"
6	
7		"gopkg.in/yaml.v3"
8	
9		"github.com/anthnel/devdesk/internal/config"
10	)
11	
12	// prices decodes a YAML mapping of model id -> rates the way the config
13	// loader does, since config.Rate can only be built by decoding.
14	func prices(t *testing.T, doc string) map[string]config.ModelPrice {
15		t.Helper()
16		var m map[string]config.ModelPrice
17		if err := yaml.Unmarshal([]byte(doc), &m); err != nil {
18			t.Fatalf("fixture YAML: %v", err)
19		}
20		return m
21	}
22	
23	// entry renders a complete price entry with the given key, then lets the
24	// caller override single lines.
25	func entry(key string, lines ...string) string {
26		if len(lines) == 0 {
27			lines = []string{"input: 1", "output: 5", "cache_write_5m: 1.25", "cache_write_1h: 2", "cache_read: 0.1"}
28		}
29		return key + ":\n  " + strings.Join(lines, "\n  ") + "\n"
30	}
31	
32	func problemByKey(ps []Problem) map[string][]string {
33		out := map[string][]string{}
34		for _, p := range ps {
35			out[p.Key] = append(out[p.Key], p.Reason)
36		}
37		return out
38	}
39	
40	func TestFromConfigAcceptsACompleteEntry(t *testing.T) {
41		tbl, probs := FromConfig(prices(t, entry("claude-x")))
42		if len(probs) != 0 {
43			t.Fatalf("problems = %v, want none", probs)
44		}
45		if tbl.Len() != 1 {
46			t.Fatalf("Len = %d, want 1", tbl.Len())
47		}
48		got, ok := tbl.Lookup("claude-x")
49		if !ok {
50			t.Fatal("claude-x not found")
51		}
52		want := Rates{Input: 1, Output: 5, CacheWrite5m: 1.25, CacheWrite1h: 2, CacheRead: 0.1}
53		if got != want {
54			t.Errorf("rates = %+v, want %+v", got, want)
55		}
56	}
57	
58	func TestFromConfigRejectsAnUnusableEntryWithoutAffectingOthers(t *testing.T) {
59		tests := []struct {
60			name       string
61			lines      []string
62			wantReason string // substring; "" = any non-empty reason
63		}{
64			{"missing input", []string{"output: 5", "cache_write_5m: 1", "cache_write_1h: 2", "cache_read: 0.1"}, "input"},
65			{"missing output", []string{"input: 1", "cache_write_5m: 1", "cache_write_1h: 2", "cache_read: 0.1"}, "output"},
66			{"missing cache_write_5m", []string{"input: 1", "output: 5", "cache_write_1h: 2", "cache_read: 0.1"}, "cache_write_5m"},
67			{"missing cache_write_1h", []string{"input: 1", "output: 5", "cache_write_5m: 1", "cache_read: 0.1"}, "cache_write_1h"},
68			{"missing cache_read", []string{"input: 1", "output: 5", "cache_write_5m: 1", "cache_write_1h: 2"}, "cache_read"},
69			{"null rate counts as missing", []string{"input: 1", "output: 5", "cache_write_5m: 1", "cache_write_1h: 2", "cache_read: null"}, "cache_read"},
70			{"text rate", []string{"input: \"5$\"", "output: 5", "cache_write_5m: 1", "cache_write_1h: 2", "cache_read: 0.1"}, "input"},
71			{"list rate", []string{"input: 1", "output: [1, 2]", "cache_write_5m: 1", "cache_write_1h: 2", "cache_read: 0.1"}, "output"},
72			{"negative", []string{"input: 1", "output: 5", "cache_write_5m: -1", "cache_write_1h: 2", "cache_read: 0.1"}, "cache_write_5m"},
73			{"NaN", []string{"input: .nan", "output: 5", "cache_write_5m: 1", "cache_write_1h: 2", "cache_read: 0.1"}, "input"},
74			{"+Inf", []string{"input: 1", "output: .inf", "cache_write_5m: 1", "cache_write_1h: 2", "cache_read: 0.1"}, "output"},
75			{"-Inf", []string{"input: 1", "output: 5", "cache_write_5m: 1", "cache_write_1h: -.inf", "cache_read: 0.1"}, "cache_write_1h"},
76		}
77		for _, tc := range tests {
78			t.Run(tc.name, func(t *testing.T) {
79				doc := entry("bad", tc.lines...) + entry("good")
80				tbl, probs := FromConfig(prices(t, doc))
81	
82				if _, ok := tbl.Lookup("bad"); ok {
83					t.Error("unusable entry is in the table")
84				}
85				if _, ok := tbl.Lookup("good"); !ok {
86					t.Error("a bad neighbour took the good entry down")
87				}
88				if tbl.Len() != 1 {
89					t.Errorf("Len = %d, want 1", tbl.Len())
90				}
91				byKey := problemByKey(probs)
92				if len(probs) != 1 || len(byKey["bad"]) != 1 {
93					t.Fatalf("problems = %+v, want exactly one for key %q", probs, "bad")
94				}
95				reason := byKey["bad"][0]
96				if reason == "" || !strings.Contains(reason, tc.wantReason) {
97					t.Errorf("reason = %q, want it to name %q", reason, tc.wantReason)
98				}
99			})
100		}
101	}
102	
103	func TestFromConfigMissingRateReasonIsExact(t *testing.T) {
104		_, probs := FromConfig(prices(t, entry("x", "input: 1", "output: 5", "cache_write_5m: 1", "cache_write_1h: 2")))
105		if len(probs) != 1 || probs[0].Key != "x" || probs[0].Reason != "incomplete: missing cache_read" {
106			t.Errorf("problems = %+v, want {x, \"incomplete: missing cache_read\"}", probs)
107		}
108	}
