110	func TestFromConfigZeroIsAValidExplicitRate(t *testing.T) {
111		tbl, probs := FromConfig(prices(t, entry("free", "input: 0", "output: 0", "cache_write_5m: 0", "cache_write_1h: 0", "cache_read: 0")))
112		if len(probs) != 0 {
113			t.Fatalf("problems = %v, want none", probs)
114		}
115		got, ok := tbl.Lookup("free")
116		if !ok || got != (Rates{}) {
117			t.Errorf("Lookup(free) = %+v, %v; want zero rates, true", got, ok)
118		}
119	}
