121	func TestFromConfigEmptyAndNil(t *testing.T) {
122		for name, in := range map[string]map[string]config.ModelPrice{"nil": nil, "empty": {}} {
123			t.Run(name, func(t *testing.T) {
124				tbl, probs := FromConfig(in)
125				if tbl.Len() != 0 || len(probs) != 0 {
126					t.Errorf("Len = %d, problems = %v; want 0, none", tbl.Len(), probs)
127				}
128				if _, ok := tbl.Lookup("anything"); ok {
129					t.Error("empty table found a model")
130				}
131			})
132		}
133	}
