135	func TestFromConfigDropsBothKeysThatCollideAfterNormalisation(t *testing.T) {
136		doc := entry("\"Claude-X \"") + entry("claude-x", "input: 9", "output: 9", "cache_write_5m: 9", "cache_write_1h: 9", "cache_read: 9") + entry("other")
137		tbl, probs := FromConfig(prices(t, doc))
138	
139		if _, ok := tbl.Lookup("claude-x"); ok {
140			t.Error("a colliding key survived: choosing one would be a guess")
141		}
142		if _, ok := tbl.Lookup("other"); !ok {
143			t.Error("an unrelated entry was dropped")
144		}
145		if tbl.Len() != 1 {
146			t.Errorf("Len = %d, want 1", tbl.Len())
147		}
148		byKey := problemByKey(probs)
149		if len(probs) != 2 || len(byKey["Claude-X "]) != 1 || len(byKey["claude-x"]) != 1 {
150			t.Fatalf("problems = %+v, want one per colliding key, with the user's own spelling", probs)
151		}
152		for k, rs := range byKey {
153			if rs[0] == "" {
154				t.Errorf("empty reason for %q", k)
155			}
156		}
157	}
