		case v < 0:
			return Rates{}, nr.name + " is negative"
		}
		*nr.dst = v
	}
	return r, ""
}

func sortProblems(ps []Problem) {
	for i := 1; i < len(ps); i++ {
		for j := i; j > 0 && (ps[j].Key < ps[j-1].Key || (ps[j].Key == ps[j-1].Key && ps[j].Reason < ps[j-1].Reason)); j-- {
