				s.Unpriced = appendOnce(s.Unpriced, m)
			}
		}
	}
	sort.Strings(s.Unpriced)
	if u.Billed.Known && allPriced {
		s.Unattributed = u.Billed.USD - sum
		s.UnattributedKnown = true
	}
	return s
}
EOF
